R.estudos=()=>head('Sessões de estudo','Histórico do tempo realmente estudado.',`<span class="pill gold">Total ${hms(totalSec())}</span>`)+`<div class="card scroll">${S.sessions.length?`<table><tr><th>Data</th><th>Matéria</th><th>Assuntos</th><th>Início</th><th>Duração</th><th></th></tr>${[...S.sessions].reverse().map(s=>`<tr><td>${fmtD(iso(new Date(s.start)),{day:'2-digit',month:'2-digit',year:'numeric'})}</td><td>${esc(s.subject)}</td><td>${esc(s.topics.join(' • '))}</td><td>${new Date(s.start).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</td><td><b>${hms(s.dur)}</b></td><td><button class="chip" data-delses="${s.id}">Excluir</button></td></tr>`).join('')}</table>`:'<div class="empty">Nenhuma sessão ainda.</div>'}</div>`;
R.questoes=()=>{const ss=Object.keys(SYL).sort(),recent=[...S.results].reverse().slice(0,6);return head('Registrar questões','Cada resposta atualiza o domínio do assunto.',`<a class="btn ghost" href="#/banco">Abrir banco</a>`)+`<div class="grid g2e"><div class="card"><form id="qf"><label class="f">Matéria</label><select id="qs">${ss.map(s=>`<option>${s}</option>`).join('')}</select><label class="f">Assunto do edital</label><select id="qt"></select><label class="f">Dificuldade</label><select id="qd"><option>Fácil</option><option selected>Média</option><option>Difícil</option></select><label class="f">Resultado</label><div class="seg"><label><input type="radio" name="ok" value="1" required>Acertei</label><label class="bad"><input type="radio" name="ok" value="0">Errei</label></div><button class="btn full">Salvar resultado</button></form></div><div class="card"><h2>Últimos registros</h2><div class="sub">Os 6 mais recentes</div>${recent.length?recent.map(r=>`<div class="rev"><span class="dot ${r.ok?'c':''}" style="${r.ok?'':'background:var(--red)'}"></span><div class="t"><b>${esc(r.topic)}</b><small>${esc(r.subject)} · ${r.diff}</small></div><span class="pill ${r.ok?'green':'red'}">${r.ok?'Acerto':'Erro'}</span></div>`).join(''):'<div class="empty">Nenhum registro ainda.</div>'}</div></div>`};
R.banco=()=>{const A=ALL(),L=bankList(),subs=[...new Set(A.map(q=>q.s))].sort(),f=R._bf||'',di=S.dinfo;
return head('Banco de questões',`${A.length} questões neste edital.`,`<a class="btn" href="#/simulado">Montar simulado</a>`)+`<div class="grid g2e" style="margin-bottom:16px"><div class="card"><h2>Importar questões</h2><div class="sub">Arquivo CSV ou JSON. Baixe o modelo para ver as colunas.</div><input type="file" id="bimp" accept=".csv,.json,.txt"><div class="row" style="margin-top:12px"><button class="chip" id="tpl">Baixar modelo CSV</button><button class="chip" id="bexp">Exportar banco</button>${S.bank.length?'<button class="chip" id="bclr">Esvaziar banco</button>':''}</div>${R._imp?`<div class="expl">${esc(R._imp)}</div>`:''}</div><div class="card"><h2>Distribuir pelo cronograma</h2><div class="sub">Cada questão vai para um dia em que o assunto está planejado, respeitando a meta diária.</div><div class="row"><button class="btn" id="dst">Distribuir agora</button>${S.dist&&Object.keys(S.dist).length?'<a class="btn ghost" href="#/treino">Abrir treino do dia</a>':''}</div>${di?`<div class="expl">${di.n} questões em ${di.days} dias.${di.un?` ${di.un} sem dia disponível.`:''}</div>`:''}</div></div><div class="chips"><button class="chip ${!f?'on':''}" data-f="">Todas</button>${subs.map(s=>`<button class="chip ${f===s?'on':''}" data-f="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="qgrid">${L.map((q,i)=>`<div class="card"><span class="pill gold">${esc(q.s)} · ${q.d}</span><h3 style="font-size:17px;margin:14px 0 8px;line-height:1.35">${esc(q.q)}</h3>${q.o.map((o,j)=>`<div class="opt" data-bk="${i}-${j}">${'ABCDE'[j]}) ${esc(o)}</div>`).join('')}<div class="expl hidden" id="bx${i}">Gabarito ${'ABCDE'[q.a]}. ${esc(q.e||'')}</div><button class="chip" style="margin-top:14px" data-show="${i}">Ver gabarito</button></div>`).join('')}</div>`};
R.simulado=()=>{if(R._sim)return head('Simulado',`${R._sim.length} questões. Responda sem consultar o gabarito.`,`<button class="btn ghost" id="newsim">Novo simulado</button>`)+quiz(R._sim,'sim','Finalizar simulado');
const n=ALL().length;return head('Simulado','Escolha o tamanho e como as questões se distribuem.')+`<div class="card" style="max-width:640px"><form id="sc"><label class="f">Número de questões (o banco tem ${n})</label><input id="sn" type="number" min="1" max="${n}" value="${Math.min(20,n)}"><label class="f">Distribuição</label><select id="sm"><option value="eq">Equilibrada</option><option value="weak">Mais questões onde meu acerto é menor</option><option value="pri">Proporcional à prioridade</option></select><label class="f" style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="su" checked style="width:auto">Priorizar questões inéditas</label><button class="btn full">Gerar simulado</button></form></div>`};
