const t=iso(),d=ds.includes(R._td)?R._td:(ds.find(x=>x>=t)||ds[0]),all=ALL(),L=S.dist[d].map(id=>all.find(q=>q.id===id)).filter(Boolean),dy=SCH.find(x=>x.d===d);R._td=d;R._tl=L;
