R.desempenho=()=>{const r=S.results,ok=r.filter(x=>x.ok).length,days=lastDays(14);return head('Desempenho','Domínio por matéria.')+`<div class="grid g3" style="margin-bottom:16px">${stat('Questões',r.length,'i','registradas','q')}${stat('Acertos',ok,'i','de '+r.length,'chart')}${stat('Média',r.length?ok/r.length*100:0,'p','aproveitamento geral','spark')}</div><div class="grid g2"><div class="card"><h2>Por matéria</h2><div class="sub">Do menor para o maior aproveitamento</div>${hbars(bySubject())}</div><div class="card"><h2>Evolução</h2><div class="sub">Aproveitamento nos últimos 14 dias</div>${line(days.map((d,i)=>{const x=r.filter(y=>y.date===d);return{i,v:x.length?accOf(x):null}}),14,days.map(d=>d.slice(8)+'/'+d.slice(5,7)))}</div></div>`};
R.edital=()=>head('Edital estruturado','Toque em um assunto para alterar o status.')+Object.entries(SYL).map(([s,ts],n)=>{const c=ts.filter(t=>tStatus(s,t)==='c').length,o=R._o||(R._o={});return`<div class="card acc ${o[s]?'open':''}" style="margin-bottom:12px" data-s="${s}"><button data-acc="${s}"><div><h3>${s}</h3><small style="color:var(--muted)">${c} de ${ts.length} consolidados</small></div><div class="row"><span class="pill ${PRI[s]==='Alta'?'gold':''}">${PRI[s]||'Média'}</span><div class="track" style="width:90px"><i class="g" style="width:${c/ts.length*100}%"></i></div></div></button><div class="body">${ts.map(t=>{const i=tInfo(s,t),st=tStatus(s,t);return`<div class="topic" data-st="${esc(s)}|${esc(t)}"><span class="dot ${st==='n'?'':st}"></span><span style="flex:1">${esc(t)}</span>${i.q?`<span class="pill ${i.c/i.q>=.8?'green':''}">${(i.c/i.q*100).toFixed(0)}% · ${i.q}q</span>`:''}</div>`}).join('')}</div></div>`}).join('');
R.ia=()=>head('Professor IA','Analisa seus dados reais.')+`<div class="grid g2"><div class="card chat"><div class="msgs" id="msgs">${(S.chat.length?S.chat:[{r:'bot',t:'Posso analisar seu ritmo, aproveitamento e revisões.'}]).map(m=>`<div class="b ${m.r}">${esc(m.t).replace(/\n/g,'<br>')}${m.src?`<small>${m.src}</small>`:''}</div>`).join('')}</div><div class="row"><input id="pr" placeholder="Ex.: O que devo estudar agora?" style="flex:1"><button class="btn" id="snd">Enviar</button></div></div><div class="card"><h2>Ações rápidas</h2><div class="pill" id="ast" style="margin:10px 0 14px">Verificando Ollama...</div><div class="grid">${['O que devo estudar agora?','Analise meu desempenho','Quais revisões devo fazer?','Monte minha próxima sessão'].map(q=>`<button class="chip" style="text-align:left;border-radius:12px" data-q="${q}">${q}</button>`).join('')}</div>${AIFORM()}</div></div>`;
