/* ---------- binds ---------- */
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove('show'),2400)};
function tick(){const a=S.active;$$('#timer').forEach(e=>e.textContent=hms(a?(Date.now()-a.start)/1000|0:0));const arc=$('#arc');if(arc){const p=planFor(),goal=p?p.h*3600:9000,cur=secOn(iso())+(a?(Date.now()-a.start)/1000:0),f=Math.min(1,cur/goal);arc.style.strokeDashoffset=528*(1-f);$('#rt').textContent=Math.round(f*100)+'%'}}
setInterval(tick,1000);
function finish(){const a=S.active;if(!a)return;const dur=Math.max(1,(Date.now()-a.start)/1000|0);S.sessions.push({id:uid(),start:a.start,dur,subject:a.subject,topics:a.topics});
a.topics.filter(t=>!/^Revisão|^Simulado/.test(t)).forEach(t=>{const sb=topicSubject(t,a.subject);[[1,'24h'],[7,'7d'],[30,'30d']].forEach(([n,ty])=>{const d=plus(n);if(!S.reviews.some(r=>r.topic===t&&r.date===d&&r.type===ty))S.reviews.push({id:uid(),date:d,subject:sb,topic:t,type:ty,done:false})})});const pl=SCH.find(x=>x.d===iso()),real=a.topics.filter(t=>!/^Revisão|^Simulado/.test(t)),extra=real.length&&(!pl||real.some(t=>!pl.t.includes(t)));S.active=null;let mg='Sessão salva. Revisões 24h, 7d e 30d criadas.';if(extra){replan();mg+=' Cronograma reajustado.'}save();toast(mg);go(true)}
const BIND={dashboard(){$('#start')?.addEventListener('click',()=>{const p=planFor();S.active={start:Date.now(),subject:p?p.s.join(' + '):'Estudo livre',topics:p?[...p.t]:[]};save();go(true)});$('#stop')?.addEventListener('click',finish);$('#xadd')?.addEventListener('click',()=>{const v=$('#xt').value;if(v&&!S.active.topics.includes(v)){S.active.topics.push(v);save();go(true)}});
$$('svg circle[data-off]').forEach(c=>requestAnimationFrame(()=>setTimeout(()=>c.style.strokeDashoffset=c.dataset.off,150)));tick()},
cronograma(){$('#cf').onsubmit=cfSubmit;const v=$('#view');v.onclick=e=>{const c=e.target.closest('.check'),ch=e.target.closest('.chip');if(c){const d=c.dataset.d;S.done[d]=!S.done[d];save();c.classList.toggle('on',!!S.done[d]);$('#d'+d).classList.toggle('done',!!S.done[d]);const n=Object.values(S.done).filter(Boolean).length;$('#prog').textContent=n+' de '+SCH.length+' concluídos';$('#pbar').style.width=n/SCH.length*100+'%';if(S.done[d])toast('Dia '+fmtD(d,{day:'2-digit',month:'2-digit'})+' concluído')}
else if(ch){if(ch.dataset.p)R._f.p=ch.dataset.p;else R._f.pend=!R._f.pend;go(true)}};$('#d'+iso())?.scrollIntoView({block:'center'})},
estudos(){$$('[data-delses]').forEach(b=>b.onclick=()=>{if(confirm('Excluir esta sessão?')){S.sessions=S.sessions.filter(s=>s.id!==b.dataset.delses);save();go(true)}})},
questoes(){const ss=$('#qs'),tt=$('#qt'),fill=()=>tt.innerHTML=SYL[ss.value].map(t=>`<option>${esc(t)}</option>`).join('');ss.onchange=fill;fill();
$('#qf').onsubmit=e=>{e.preventDefault();const ok=+$('input[name=ok]:checked').value;S.results.push({id:uid(),date:iso(),subject:ss.value,topic:tt.value,diff:$('#qd').value,ok});const k=tk(ss.value,tt.value),i=S.topics[k]||(S.topics[k]={q:0,c:0});i.q++;i.c+=ok;save();toast(ok?'Acerto registrado':'Erro registrado');const s0=ss.value,t0=tt.selectedIndex;go(true);$('#qs').value=s0;$('#qs').onchange();$('#qt').selectedIndex=t0}},
banco(){$$('[data-show]').forEach(b=>b.onclick=()=>{const q=bankList()[b.dataset.show];$('#bx'+b.dataset.show).classList.remove('hidden');$(`[data-bk="${b.dataset.show}-${q.a}"]`).classList.add('ok');b.remove()});
$$('[data-f]').forEach(b=>b.onclick=()=>{R._bf=b.dataset.f;go(true)});$('#bimp').onchange=async e=>{const f=e.target.files[0];if(f){R._imp=await importFile(f);go(true)}};
$('#tpl').onclick=()=>dl('modelo-questoes.csv','\uFEFF'+TPL,'text/csv');$('#bexp').onclick=()=>dl('banco-questoes.json',JSON.stringify(ALL().map(q=>({materia:q.s,assunto:q.t,enunciado:q.q,alternativas:q.o,gabarito:'ABCDE'[q.a],explicacao:q.e,dificuldade:q.d})),null,1),'application/json');
$('#bclr')&&($('#bclr').onclick=()=>{if(confirm('Apagar todas as questões deste edital?')){S.bank=[];S.dist={};S.dinfo=null;save();go(true)}});$('#dst').onclick=()=>{distribute();go(true)}},
simulado(){if(R._sim){$('#sim').onsubmit=e=>{e.preventDefault();grade(R._sim)};$('#newsim').onclick=()=>{R._sim=null;go(true)}}else $('#sc').onsubmit=e=>{e.preventDefault();const L=mkSim(+$('#sn').value||10,$('#sm').value,$('#su').checked);if(!L.length)return toast('O banco está vazio');R._sim=L;go()}},
treino(){$('#td')&&($('#td').onchange=e=>{R._td=e.target.value;go(true)});$('#tr')&&($('#tr').onsubmit=e=>{e.preventDefault();grade(R._tl)})},
revisoes(){$$('[data-r]').forEach(b=>b.onclick=()=>{const r=S.reviews.find(x=>x.id===b.dataset.r);r.done=!r.done;save();go(true)})},
edital(){$$('[data-acc]').forEach(b=>b.onclick=()=>{const c=b.parentElement;c.classList.toggle('open');R._o[b.dataset.acc]=c.classList.contains('open')});$$('[data-st]').forEach(r=>r.onclick=()=>{const [s,t]=r.dataset.st.split('|'),k=tk(s,t),i=S.topics[k]||(S.topics[k]={q:0,c:0});i.st={n:'d',d:'c',c:'n'}[tStatus(s,t)];save();go(true)})},
ia(){const m=$('#msgs'),send=async t=>{t=t.trim();if(!t)return;$('#pr').value='';S.chat.push({r:'me',t});m.insertAdjacentHTML('beforeend',`<div class="b me">${esc(t)}</div>`);const a=await advise(t);S.chat.push({r:'bot',t:a.t,src:a.src});save();m.insertAdjacentHTML('beforeend',`<div class="b bot">${esc(a.t).replace(/\n/g,'<br>')}<small>${a.src}</small></div>`);m.scrollTop=m.scrollHeight};
$('#snd').onclick=()=>send($('#pr').value);$('#pr').onkeydown=e=>e.key==='Enter'&&send($('#pr').value);$$('[data-q]').forEach(b=>b.onclick=()=>send(b.dataset.q));m.scrollTop=m.scrollHeight;
chk();aiBind()},
dados(){setSync(SYNC);$('#syn')&&($('#syn').onclick=()=>reconcile(false));$('#gol')&&($('#gol').onclick=()=>{document.getElementById('app').classList.add('hidden');document.getElementById('login').classList.remove('hidden')});
$('#exp').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(DB)],{type:'application/json'}));a.download='pmpe-backup-'+iso()+'.json';a.click()};
$('#imp').onchange=e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{try{const j=JSON.parse(t),ow=DB.owner;DB=j.eds?{...j,logged:true}:{user:DB.user,logged:true,chat:[],cur:'pmpe',eds:{pmpe:mkPmpe(j)}};DB.ai??={prov:'ollama',url:'http://127.0.0.1:11434',model:'llama3.2:3b',key:''};DB.owner=ow;save();useEd();fillEd();toast('Backup restaurado');go(true)}catch{toast('Arquivo inválido')}})};
$('#rst').onclick=()=>{if(confirm('Apagar todo o progresso deste navegador?')){DB={user:DB.user,logged:true,chat:[],cur:'pmpe',eds:{pmpe:mkPmpe({})},ai:DB.ai,owner:DB.owner};save();useEd();fillEd();go(true)}}}};
/* ---------- Professor IA ---------- */
function ctx(){const r=S.results,ok=r.filter(x=>x.ok).length,t=iso(),p=planFor();return{horas:+(totalSec()/3600).toFixed(2),questoes:r.length,acertos:ok,aproveitamento:r.length?+(ok/r.length*100).toFixed(1):0,revisoes_vencidas:S.reviews.filter(x=>!x.done&&x.date<=t).length,proximas:S.reviews.filter(x=>!x.done).slice(0,6),pontos_fracos:bySubject().slice(0,4),plano:p}}
async function advise(q){const c=ctx();let why='';try{const t=await llm(SYS(),'CONTEXTO: '+JSON.stringify(c)+'\nPEDIDO: '+q);if(t)return{t:t.trim(),src:'IA: '+PRE[DB.ai.prov][2]+' · '+DB.ai.model}}catch(e){why=e.message||'falhou'}
const p=q.toLowerCase();let t;if(!c.questoes)t='Ainda não tenho questões para personalizar seu desempenho.';
else if(p.includes('revis'))t=c.revisoes_vencidas?`Você tem ${c.revisoes_vencidas} revisão(ões) vencida(s).`:c.proximas[0]?`Próxima revisão: ${c.proximas[0].subject}, ${c.proximas[0].topic} (${c.proximas[0].type}).`:'Sem revisões pendentes.';
else if(p.includes('desempenho')||p.includes('acerto'))t=`Aproveitamento de ${c.aproveitamento}% em ${c.questoes} questões. Menores: ${c.pontos_fracos.map(x=>x.n+' ('+x.r.toFixed(0)+'%)').join(', ')||'—'}.`;
else if(p.includes('agora')||p.includes('estudar')||p.includes('sessão'))t=`Siga o plano${c.plano?' de '+fmtD(c.plano.d,{day:'2-digit',month:'2-digit'})+': '+c.plano.s.join(' + '):''} (${c.plano?c.plano.h:2.5}h). Revisões vencidas: ${c.revisoes_vencidas}.`;
else t=`Você tem ${c.questoes} questões, ${c.aproveitamento}% de acerto e ${c.horas}h de estudo.`;return{t,src:'Modo regras'+(why?' ('+why+')':'')}}
/* ---------- editais, replanejamento e IA ---------- */
const PW={Alta:3,Média:2,Complementar:1};
const dayList=(from,end,wd)=>{const o=[];for(let d=dObj(from);iso(d)<=end;d.setDate(d.getDate()+1)){const w=d.getDay();if(wd>=7||(wd==6&&w!==0)||(wd==5&&w>0&&w<6))o.push(iso(d))}return o};
function seq(tp){const by={};tp.forEach(([s,t])=>(by[s]??=[]).push(t));const acc=Object.fromEntries(bySubject().map(x=>[x.n,x.r])),c={},out=[],w=s=>(PW[PRI[s]]||2)*(acc[s]==null?1:1+(100-acc[s])/100);
for(;;){const ss=Object.keys(by).filter(s=>by[s].length);if(!ss.length)break;const p=ss.reduce((a,b)=>((c[a]||0)+1)/w(a)<=((c[b]||0)+1)/w(b)?a:b);c[p]=(c[p]||0)+1;out.push([p,by[p].shift()])}return out}
function build(from,tp,cfg){const ds=dayList(from,cfg.end,cfg.wd);if(!ds.length)return[];const rv=Math.min(7,Math.floor(ds.length*.12)),nd=ds.length-rv,sq=seq(tp),T=sq.length,q=Math.max(10,Math.round(cfg.h*14/5)*5),out=[];let u=0;
ds.forEach((d,i)=>{if(i>=nd){out.push({d,p:'Revisão final',s:['Revisão geral','Simulado'],t:['Revisão dos pontos fracos','Simulado e correção'],h:cfg.h,q:q+10});return}
const k=T<nd?(i<T?1:0):Math.floor((i+1)*T/nd)-Math.floor(i*T/nd),it=sq.splice(0,k);if(!it.length){out.push({d,p:'Revisão',s:['Revisão geral'],t:['Revisão dos pontos fracos'],h:cfg.h,q});return}
out.push({d,p:i<nd*.7?'Base':'Aprofundamento',s:[...new Set(it.map(x=>x[0]))],t:it.map(x=>x[1]),h:cfg.h,q})});return out}
function covered(){const c=new Set();S.sessions.forEach(x=>x.topics.forEach(t=>c.add(t)));for(const k in S.topics){const st=S.topics[k].st,t=k.split('|').slice(1).join('|');if(st==='n')c.delete(t);else if(st)c.add(t)}return c}
function replan(){const cfg=E().cfg,t=iso(),keep=SCH.filter(x=>x.d<t||(x.d===t&&S.done[t])),cv=covered();keep.forEach(x=>{if(S.done[x.d])x.t.forEach(y=>cv.add(y))});const from=keep.length&&keep.at(-1).d===t?plus(1):t,rest=[];
Object.entries(SYL).forEach(([s,ts])=>ts.forEach(x=>{if(!cv.has(x))rest.push([s,x])}));const nw=build(from,rest,cfg);E().sch=[...keep,...nw];SCH=E().sch;S.dist={};S.dinfo=null;if(ALL().length)distribute();save();return{left:rest.length,days:nw.length}}
function ADJ(){const c=E().cfg;return`<div class="card" style="margin-bottom:16px"><h2>Ajustar plano</h2><div class="sub">Dias passados e concluídos são mantidos.</div><form id="cf" class="row" style="align-items:flex-end"><div><label class="f">Data da prova</label><input type="date" id="cend" value="${c.end}"></div><div><label class="f">Horas por dia</label><input type="number" step="0.5" min="0.5" max="12" id="chh" value="${c.h}" style="width:110px"></div><div><label class="f">Dias por semana</label><select id="cwd">${[5,6,7].map(n=>`<option ${c.wd==n?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn">Reajustar agora</button></form></div>`}
function cfSubmit(e){e.preventDefault();const c=E().cfg,end=$('#cend').value;if(!end||end<=iso())return toast('Informe uma data futura');c.end=end;c.h=+$('#chh').value||c.h;c.wd=+$('#cwd').value;if(R._f)R._f.p='Todas';const r=replan();save();toast('Cronograma reajustado: faltam '+r.left+' assuntos');go(true)}
const PICK=()=>`<div class="row" style="margin-top:14px"><select id="xt" style="flex:1;min-width:220px"><option value="">Estudei outro assunto...</option>${Object.entries(SYL).map(([s,ts])=>`<optgroup label="${esc(s)}">${ts.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</optgroup>`).join('')}</select><button class="chip" id="xadd">Adicionar</button></div><div class="sub" style="margin:10px 0 0">Nesta sessão: ${S.active.topics.map(esc).join(' • ')||'nenhum assunto'}. Ao finalizar, o cronograma se reajusta.</div>`;
function parseSyl(t){const syl={},pri={};let cur=null;t.split(/\r?\n/).forEach(l=>{l=l.trim();if(!l)return;const m=l.match(/^[-•*–]\s*(.+)$/)||l.match(/^\d+[\.\)]\s+(.+)$/);if(m&&cur)syl[cur].push(m[1].trim());else{const h=l.match(/^(.*?)\s*(?:\[(alta|média|media|complementar)\])?\s*:?\s*$/i);cur=h[1].trim();if(!cur)return;syl[cur]??=[];if(h[2])pri[cur]=/^a/i.test(h[2])?'Alta':/^c/i.test(h[2])?'Complementar':'Média'}});Object.keys(syl).forEach(k=>{if(!syl[k].length)delete syl[k];else pri[k]??='Média'});return{syl,pri}}
function toText(n,t){try{if(/\.json$/i.test(n)){const j=JSON.parse(t),m=j.materias||j.syllabus||j;return Object.entries(m).map(([k,v])=>k+'\n'+v.map(x=>'- '+x).join('\n')).join('\n')}if(/\.csv$/i.test(n)){const g={};csv(t).forEach(r=>{const m={};for(const x in r)m[nz(x)]=r[x];const s=m.materia||m.disciplina;if(!s)return;(g[s]??={p:m.prioridade||'',t:[]}).t.push(m.assunto||m.topico||'')});return Object.entries(g).map(([k,v])=>k+(v.p?' ['+v.p+']':'')+'\n'+v.t.filter(Boolean).map(x=>'- '+x).join('\n')).join('\n')}}catch{}return t}
function fillEd(){const s=$('#edsel');if(s)s.innerHTML=Object.values(DB.eds).map(e=>`<option value="${e.id}" ${e.id===DB.cur?'selected':''}>${esc(e.name)}</option>`).join('')}
function switchEd(id){DB.cur=id;save();useEd();R._f=null;R._o=null;R._sim=null;R._bf='';R._td=null;R._imp=null;fillEd();go()}
R.editais=()=>head('Editais','Cada edital tem suas matérias, cronograma, banco e progresso separados.')+`<div class="grid g3" style="margin-bottom:16px">${Object.values(DB.eds).map(e=>`<div class="card tilt"><span class="pill ${e.id===DB.cur?'gold':''}">${e.id===DB.cur?'Em uso':'Edital'}</span><h2 style="font-size:24px;margin:12px 0 4px">${esc(e.name)}</h2><div class="sub">${Object.keys(e.syl).length} matérias · ${Object.values(e.syl).flat().length} assuntos · ${e.bank.length} questões · prova em ${fmtD(e.cfg.end)}</div><div class="row">${e.id===DB.cur?'':`<button class="btn" data-use="${e.id}">Usar</button>`}${Object.keys(DB.eds).length>1?`<button class="btn danger" data-del="${e.id}">Excluir</button>`:''}</div></div>`).join('')}</div><div class="card"><h2>Importar novo edital</h2><div class="sub">Cole matérias/assuntos ou envie CSV (materia;assunto;prioridade) ou JSON.</div><form id="ef"><div class="grid g2e"><div><label class="f">Nome (ex.: PCPE)</label><input id="enm" required><label class="f">Data da prova</label><input type="date" id="een" required><div class="row"><div><label class="f">Horas por dia</label><input type="number" id="ehh" step="0.5" min="0.5" value="3" style="width:110px"></div><div><label class="f">Dias por semana</label><select id="ewd"><option>5</option><option selected>6</option><option>7</option></select></div></div><label class="f">Arquivo (opcional)</label><input type="file" id="efile" accept=".csv,.json,.txt"></div><div><label class="f">Matérias e assuntos</label><textarea id="etx" placeholder="Direito Penal [Alta]&#10;- Teoria do crime&#10;Português [Média]&#10;- Interpretação de texto"></textarea></div></div><button class="btn full">Criar edital e gerar cronograma</button></form></div>`;
BIND.editais=()=>{$$('[data-use]').forEach(b=>b.onclick=()=>switchEd(b.dataset.use));$$('[data-del]').forEach(b=>b.onclick=()=>{const e=DB.eds[b.dataset.del];if(!confirm('Excluir '+e.name+' e todo o progresso dele?'))return;delete DB.eds[e.id];if(DB.cur===e.id)DB.cur=Object.keys(DB.eds)[0];save();useEd();fillEd();go(true)});
$('#efile').onchange=async e=>{const f=e.target.files[0];if(f)$('#etx').value=toText(f.name,(await f.text()).replace(/^\uFEFF/,''))};
$('#ef').onsubmit=e=>{e.preventDefault();const{syl,pri}=parseSyl($('#etx').value);if(!Object.keys(syl).length)return toast('Não encontrei matérias.');const cfg={end:$('#een').value,h:+$('#ehh').value||3,wd:+$('#ewd').value||6};if(!cfg.end||cfg.end<=iso())return toast('Informe uma data futura');const id='e'+uid();DB.eds[id]={id,name:$('#enm').value.trim()||'Novo edital',syl,pri,sch:[],cfg,...blank()};switchEd(id);const r=replan();save();toast('Edital criado: '+r.days+' dias de plano');location.hash='#/cronograma'}};
const PRE={ollama:['http://127.0.0.1:11434','llama3.2:3b','Ollama (neste computador)'],groq:['https://api.groq.com/openai/v1','llama-3.3-70b-versatile','Groq'],gemini:['https://generativelanguage.googleapis.com/v1beta/openai','gemini-2.5-flash','Google Gemini'],openrouter:['https://openrouter.ai/api/v1','','OpenRouter'],rules:['','','Sem IA (modo regras)']};
const SYS=()=>`Você é o Professor IA do edital ${E().name}. Seja objetivo, responda em português do Brasil e use APENAS os dados do contexto. Não invente dados.`;
async function llm(sys,usr){const a=DB.ai,u=a.url.replace(/\/$/,''),m=[{role:'system',content:sys},{role:'user',content:usr}];if(a.prov==='rules')return null;
if(a.prov==='ollama'){const r=await fetch(u+'/api/chat',{method:'POST',signal:AbortSignal.timeout(60000),body:JSON.stringify({model:a.model,stream:false,options:{temperature:.3},messages:m})});return(await r.json()).message?.content}
if(!a.key)throw new Error('falta a chave de API');const r=await fetch(u+'/chat/completions',{method:'POST',signal:AbortSignal.timeout(60000),headers:{'Content-Type':'application/json',Authorization:'Bearer '+a.key},body:JSON.stringify({model:a.model,temperature:.3,messages:m})}),j=await r.json();if(!r.ok)throw new Error(j.error?.message||'erro '+r.status);return j.choices?.[0]?.message?.content}
const AIFORM=()=>{const a=DB.ai,hid=a.prov==='ollama'||a.prov==='rules';return`<h2 style="margin-top:24px">Conectar IA</h2><div class="sub">A chave fica só neste navegador e não sobe para a nuvem.</div><select id="aip">${Object.entries(PRE).map(([k,v])=>`<option value="${k}" ${a.prov===k?'selected':''}>${v[2]}</option>`).join('')}</select><label class="f">Endereço</label><input id="aiu" value="${esc(a.url)}"><label class="f">Modelo</label><input id="aim" value="${esc(a.model)}"><div id="aikw" style="${hid?'display:none':''}"><label class="f">Chave de API</label><input id="aik" type="password" value="${esc(a.key)}" autocomplete="off"></div><div class="row" style="margin-top:14px"><button class="btn" id="aisv">Salvar</button><button class="btn ghost" id="aitt">Testar</button></div>`};
function chk(){const a=DB.ai,e=$('#ast');if(!e)return;e.textContent=a.prov==='rules'?'○ Modo regras (sem IA)':a.prov==='ollama'?'Verificando Ollama...':(a.key?'● '+PRE[a.prov][2]+' configurado':'○ Falta a chave de API');
if(a.prov==='ollama')fetch(a.url.replace(/\/$/,'')+'/api/tags',{signal:AbortSignal.timeout(2500)}).then(r=>r.json()).then(()=>{const x=$('#ast');if(x)x.textContent='● Ollama conectado'}).catch(()=>{const x=$('#ast');if(x)x.textContent='○ Ollama offline · modo regras'})}
function aiBind(){const ap=$('#aip'),sv=()=>{DB.ai={prov:ap.value,url:$('#aiu').value.trim(),model:$('#aim').value.trim(),key:$('#aik').value.trim()};save()};
ap.onchange=()=>{const p=PRE[ap.value];$('#aiu').value=p[0];$('#aim').value=p[1];$('#aikw').style.display=ap.value==='ollama'||ap.value==='rules'?'none':''};
$('#aisv').onclick=()=>{sv();toast('IA salva');chk()};$('#aitt').onclick=async()=>{sv();const e=$('#ast');e.textContent='Testando...';try{const t=await llm('Responda apenas OK.','teste');e.textContent=t?'● Funcionou: '+t.trim().slice(0,40):'○ Modo regras'}catch(x){e.textContent='○ Falhou: '+(x.message||'sem resposta')}}}
/* ---------- nuvem (Supabase + Firebase) ---------- */
const payload=()=>({eds:DB.eds,cur:DB.cur,chat:DB.chat,rev:DB.rev});
async function pull(){if(!window.SB)return null;const{data,error}=await SB.from('study_data').select('data,updated_at').eq('user_id',DB.owner).maybeSingle();if(error)throw error;return data}
async function pushNow(){if(!window.SB||!DB.owner)return;clearTimeout(syncT);syncT=null;setSync('busy');try{const{error}=await SB.from('study_data').upsert({user_id:DB.owner,data:payload(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;setSync('ok')}catch(e){setSync('err',e)}}
function push(){if(!window.SB||!DB.logged||!DB.owner)return;clearTimeout(syncT);setSync('pend');syncT=setTimeout(pushNow,2500)}
function setSync(st,e){SYNC=window.SB&&DB.logged&&DB.owner?st:'local';if(e)SYNCERR=/relation.*does not exist|schema cache/i.test(e.message)?'Falta criar a tabela no Supabase (rode o supabase-setup.sql).':/jwt|token|unauthor/i.test(e.message)?'Sessão expirada. Entre novamente.':/fetch|network|offline/i.test(e.message)?'Sem conexão. Fica salvo localmente.':e.message;else if(st==='ok')SYNCERR='';
const t={local:'○ Modo local',ok:'☁ Sincronizado',busy:'☁ Sincronizando…',pend:'☁ Alterações pendentes',err:'⚠ '+(SYNCERR||'Falha ao sincronizar')}[SYNC];$$('#sync,#sync2').forEach(x=>{x.textContent=t;x.className='pill '+(SYNC==='ok'?'green':SYNC==='err'?'red':'')})}
const hasProg=()=>Object.keys(DB.eds).length>1||Object.values(DB.eds).some(e=>e.sessions.length||e.results.length||Object.values(e.done).some(Boolean));
function applyRemote(rd){DB.eds=rd.eds;DB.cur=DB.eds[rd.cur]?rd.cur:Object.keys(DB.eds)[0];DB.chat=rd.chat||[];DB.rev=rd.rev||0;persist();useEd();fillEd();if(DB.logged)go(true)}
async function reconcile(first){if(!window.SB||!DB.owner)return;setSync('busy');try{
if(DB.owner&&DB.owner!==window.__fbUid){DB={user:DB.user,logged:DB.logged,chat:[],cur:'pmpe',eds:{pmpe:mkPmpe({})},ai:DB.ai,rev:0,owner:window.__fbUid};useEd();persist()}
const r=await pull(),rd=r&&r.data;if(!rd||!rd.eds){DB.owner=window.__fbUid;await pushNow();return}
let useRemote=(rd.rev||0)>(DB.rev||0);
if(first&&!DB.owner)useRemote=hasProg()?confirm('Há dados neste navegador e outros na nuvem.\n\nOK = usar os da nuvem.\nCancelar = enviar os deste navegador e substituir a nuvem.'):true;
if(useRemote){applyRemote(rd);setSync('ok')}else{DB.owner=window.__fbUid;await pushNow()}}catch(e){setSync('err',e)}}
const CLOUDCARD=()=>`<div class="card"><h2>Conta e nuvem</h2><div class="sub">${DB.owner?'Conectado como '+esc(DB.user.email||DB.user.name)+'. Cada alteração sobe sozinha.':'Modo local: seus dados ficam só neste navegador.'}</div><div class="pill" id="sync2" style="margin-bottom:14px;white-space:normal"></div><div class="row">${DB.owner?'<button class="btn" id="syn">Sincronizar agora</button>':'<button class="btn" id="gol">Entrar com Google</button>'}</div></div>`;
