/* ---------- login Google ---------- */
function bindAuth(){
  const btn=document.getElementById('glogin');
  if(btn&&window.FB?.ready){
    btn.onclick=async()=>{
      const er=document.getElementById('err');er.textContent='';
      try{btn.disabled=true;await FB.loginGoogle()}catch(e){er.textContent=e.message||'Falha no login';btn.disabled=false}
    };
  }else if(btn){btn.onclick=()=>{document.getElementById('err').textContent='Firebase não configurado. Preencha config.js.'}}
  if(window.FB?.ready){
    FB.onChange(async u=>{
      if(u){window.__fbUid=u.uid;DB.user={name:u.displayName||u.email.split('@')[0],email:u.email};DB.logged=true;persist();if(window.SB){try{await reconcile(true)}catch(e){}}show()}
      else{if(!DB.loggedLocal){DB.logged=false;persist();show()}}
    });
  }
  document.getElementById('llc').onclick=()=>{DB.loggedLocal=true;DB.user={name:'Aluno',email:''};DB.owner=null;DB.logged=true;persist();show()};
  document.getElementById('out').onclick=async()=>{if(window.FB?.ready&&FB.current()){try{await FB.logout()}catch{}}DB.logged=false;DB.loggedLocal=false;persist();show()};
}
