addEventListener('mousemove',e=>{m.x=e.clientX;m.y=e.clientY;const d=document.documentElement.style;d.setProperty('--mx',m.x+'px');d.setProperty('--my',m.y+'px');const t=e.target.closest?.('.tilt,.login-card');if(t){const b=t.getBoundingClientRect(),px=(e.clientX-b.left)/b.width,py=(e.clientY-b.top)/b.height;t.style.setProperty('--ry',((px-.5)*7)+'deg');t.style.setProperty('--rx',((.5-py)*7)+'deg');t.style.setProperty('--gx',px*100+'%');t.style.setProperty('--gy',py*100+'%')}});
